import Metal
import QuartzCore
import ScreenSaver
import os

private let log = Logger(subsystem: "com.bosse.starfields.metalsaver", category: "saver")

/// Native screen saver (option B): light-speed streaks from one full-screen
/// Metal fragment shader, generated by impellerc from
/// shaders/hyperspace_saver.frag (the same GLSL the app's Hyperspace renderer
/// is built from), with a periodic jump to light speed (JumpCycle).
///
/// Frames are paced by a display link of the view's own display. In
/// legacyScreenSaver only the main display's view gets a `window.screen` (see
/// the Flutter saver, macos_saver/), so the others find their `NSScreen` by
/// size. The host's animation timer (`animateOneFrame`) is the fallback: it
/// drives all views from one main-thread timer, and a 60 Hz display's
/// blocking `nextDrawable` then made the 120/240 Hz displays judder.
///
/// Built and installed by tool/build_metal_saver.sh.
@objc(StarfieldsMetalSaverView)
final class StarfieldsMetalSaverView: ScreenSaverView {
  private let metalLayer = CAMetalLayer()
  private var cycle = JumpCycle()
  private var startTime: CFTimeInterval = 0
  private var stats = FrameStats()
  private var stopObserver: NSObjectProtocol?
  private var displayLink: AnyObject?  // CADisplayLink (macOS 14+)

  /// Same density as the Flutter saver's star count would give.
  private static let stars = 2000.0

  override init?(frame: NSRect, isPreview: Bool) {
    super.init(frame: frame, isPreview: isPreview)
    log.notice("init frame=\(NSStringFromRect(frame), privacy: .public) preview=\(isPreview)")
    animationTimeInterval = 1.0 / 120.0
    guard let renderer = Renderer.shared else { return nil }
    metalLayer.device = renderer.device
    metalLayer.pixelFormat = .bgra8Unorm
    metalLayer.colorspace = CGColorSpace(name: CGColorSpace.sRGB)
    metalLayer.isOpaque = true
    metalLayer.framebufferOnly = true
    // The host's timer paces the frames; don't let nextDrawable stall it.
    metalLayer.allowsNextDrawableTimeout = true
    metalLayer.backgroundColor = NSColor.black.cgColor
    wantsLayer = true
    layer = metalLayer
  }

  required init?(coder: NSCoder) {
    super.init(coder: coder)
  }

  deinit {
    log.notice("deinit")
  }

  /// Device pixels per point. In legacyScreenSaver only the main display's
  /// view gets a `window.screen`; the other windows report the main display's
  /// scale (2 on a 1x display). Their view fills its display, so the screen
  /// with the same size tells the scale.
  private var backingScale: CGFloat { displayScreen?.backingScaleFactor ?? window?.backingScaleFactor ?? 2 }

  /// The display this view fills: its window's screen, or else the only
  /// screen of the same size.
  private var displayScreen: NSScreen? {
    if let screen = window?.screen { return screen }
    let sameSize = NSScreen.screens.filter { $0.frame.size == bounds.size }
    return sameSize.count == 1 ? sameSize[0] : nil
  }

  override func viewDidChangeBackingProperties() {
    super.viewDidChangeBackingProperties()
    updateDrawableSize()
  }

  override func setFrameSize(_ newSize: NSSize) {
    super.setFrameSize(newSize)
    updateDrawableSize()
  }

  /// Render scale (device pixels per point drawn): at most the display's,
  /// capped by `renderScaleCap`; the layer scales the drawable up. At light
  /// speed the shader checks ~40 cells per pixel; at 2x three displays were
  /// GPU-bound (51-80 fps), at 1.5x they keep up and look the same.
  private var renderScale: CGFloat { min(backingScale, Self.renderScaleCap) }

  /// Frames per second at most, on every display: a screen saver need not
  /// burn energy at 120 or 240 Hz. (On the 240 Hz display legacyScreenSaver
  /// also intermittently froze 3/4 of the image, at 120 and 240 fps alike - a
  /// host quirk that moved between displays when their refresh rates changed;
  /// Apple's Flurry, at 60, behaved.) Overridable for testing:
  /// STARFIELDS_MAX_FPS.
  private static let maxFrameRate: Float =
    ProcessInfo.processInfo.environment["STARFIELDS_MAX_FPS"].flatMap(Float.init) ?? 60

  /// Overridable for testing: STARFIELDS_RENDER_SCALE.
  private static let renderScaleCap: CGFloat =
    ProcessInfo.processInfo.environment["STARFIELDS_RENDER_SCALE"].flatMap(Double.init).map { CGFloat($0) } ?? 1.5

  private func updateDrawableSize() {
    metalLayer.contentsScale = backingScale
    metalLayer.drawableSize = CGSize(width: bounds.width * renderScale, height: bounds.height * renderScale)
  }

  override func startAnimation() {
    super.startAnimation()
    let screen = window?.screen.map { NSStringFromRect($0.frame) } ?? "none"
    log.notice("startAnimation \(Int(self.bounds.width))x\(Int(self.bounds.height)) @\(self.backingScale)x render \(self.renderScale)x screen=\(screen, privacy: .public)")
    updateDrawableSize()
    startTime = CACurrentMediaTime()
    cycle = JumpCycle()
    stats = FrameStats()
    if #available(macOS 14, *), let screen = displayScreen {
      let link = screen.displayLink(target: self, selector: #selector(displayLinkFired))
      link.preferredFrameRateRange = CAFrameRateRange(
        minimum: min(30, Self.maxFrameRate), maximum: Self.maxFrameRate, preferred: Self.maxFrameRate)
      link.add(to: .main, forMode: .common)
      displayLink = link
    }
    log.notice("pacing: \(self.displayLink == nil ? "host timer" : "display link, at most \(Self.maxFrameRate) fps", privacy: .public)")
    stopObserver = DistributedNotificationCenter.default().addObserver(
      forName: NSNotification.Name("com.apple.screensaver.willstop"),
      object: nil,
      queue: .main
    ) { [weak self] _ in
      log.notice("willstop notification")
      self?.stopAnimation()
    }
  }

  override func stopAnimation() {
    if let stopObserver {
      DistributedNotificationCenter.default().removeObserver(stopObserver)
      self.stopObserver = nil
      log.notice("stopAnimation after \(CACurrentMediaTime() - self.startTime, format: .fixed(precision: 1)) s")
    }
    if #available(macOS 14, *) { (displayLink as? CADisplayLink)?.invalidate() }
    displayLink = nil
    super.stopAnimation()
  }

  override func draw(_ rect: NSRect) {
    // Layer-backed: drawing happens in animateOneFrame.
  }

  override func animateOneFrame() {
    if displayLink == nil { renderFrame() }
  }

  @available(macOS 14, *)
  @objc private func displayLinkFired(_ link: CADisplayLink) {
    renderFrame()
  }

  private func renderFrame() {
    stats.ticks += 1
    defer {
      if let report = stats.report(now: CACurrentMediaTime()) {
        log.notice("\(Int(self.bounds.width))x\(Int(self.bounds.height)) @\(self.backingScale)x: \(report, privacy: .public)")
      }
    }
    guard let renderer = Renderer.shared else { return }
    let now = CACurrentMediaTime() - startTime
    cycle.update(now)
    let drive = cycle.drive
    let travel = drive.travel(now)
    let state = drive.state(now)
    let wrap = HyperspaceDrive.row * HyperspaceDrive.rowPeriod
    let uniforms = HyperspaceUniforms(
      size: SIMD2(Float(bounds.width), Float(bounds.height)),
      density: Float(min(1, Self.stars / HyperspaceDrive.cells)),
      // Wrapped in Double so 32-bit GPU floats never see a large value.
      shift: SIMD4(HyperspaceDrive.layerSpeeds.map { Float(($0 * travel).truncatingRemainder(dividingBy: wrap)) }),
      length: SIMD4(HyperspaceDrive.layerSpeeds.map { Float($0 * HyperspaceDrive.lengthPerSpeed * state.stretch) }),
      glow: Float(state.glow),
      width: Float(state.width),
      boost: Float(state.boost)
    )
    let cpuStart = CACurrentMediaTime()
    guard let drawable = metalLayer.nextDrawable() else {
      stats.missedDrawables += 1
      return
    }
    renderer.draw(to: drawable, uniforms: uniforms) { [weak self] gpuMillis in
      DispatchQueue.main.async { self?.stats.gpuFrame(millis: gpuMillis) }
    }
    stats.frame(cpuMillis: (CACurrentMediaTime() - cpuStart) * 1000)
  }
}

/// The uniforms of shaders/hyperspace_saver.frag. impellerc binds each one to
/// its own fragment buffer, in declaration order.
private struct HyperspaceUniforms {
  var size: SIMD2<Float>  // buffer 0, logical pixels
  var density: Float  // 1
  var shift: SIMD4<Float>  // 2
  var length: SIMD4<Float>  // 3
  var glow: Float  // 4
  var width: Float  // 5
  var boost: Float  // 6
}

/// Device, queue and pipeline, shared by all views of the host process.
private final class Renderer {
  static let shared: Renderer? = Renderer()

  let device: MTLDevice
  private let queue: MTLCommandQueue
  private let pipeline: MTLRenderPipelineState

  private init?() {
    let start = CACurrentMediaTime()
    guard
      let device = MTLCreateSystemDefaultDevice(),
      let queue = device.makeCommandQueue(),
      let vertexSource = Self.resource("FullScreen"),
      let fragmentSource = Self.resource("HyperspaceSaver")
    else {
      log.error("Metal setup failed (device, queue or shader sources)")
      return nil
    }
    do {
      // Two libraries: each source includes metal_stdlib and defines helpers.
      let vertexLibrary = try device.makeLibrary(source: vertexSource, options: nil)
      let fragmentLibrary = try device.makeLibrary(source: fragmentSource, options: nil)
      let descriptor = MTLRenderPipelineDescriptor()
      descriptor.vertexFunction = vertexLibrary.makeFunction(name: "fullScreenVertex")
      // impellerc names the entry point <shader file name>_fragment_main.
      descriptor.fragmentFunction = fragmentLibrary.makeFunction(name: "hyperspace_saver_fragment_main")
      descriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
      pipeline = try device.makeRenderPipelineState(descriptor: descriptor)
    } catch {
      log.error("shader compile failed: \(error.localizedDescription, privacy: .public)")
      return nil
    }
    self.device = device
    self.queue = queue
    log.notice("Metal ready on \(device.name, privacy: .public) in \((CACurrentMediaTime() - start) * 1000, format: .fixed(precision: 1)) ms")
  }

  private static func resource(_ name: String) -> String? {
    guard let url = Bundle(for: StarfieldsMetalSaverView.self).url(forResource: name, withExtension: "metal") else {
      return nil
    }
    return try? String(contentsOf: url, encoding: .utf8)
  }

  /// Encodes and presents one frame; `gpuTime` gets the GPU time in ms
  /// (on a Metal thread).
  func draw(to drawable: CAMetalDrawable, uniforms: HyperspaceUniforms, gpuTime: @escaping (Double) -> Void) {
    let pass = MTLRenderPassDescriptor()
    pass.colorAttachments[0].texture = drawable.texture
    pass.colorAttachments[0].loadAction = .dontCare
    pass.colorAttachments[0].storeAction = .store
    guard let buffer = queue.makeCommandBuffer(), let encoder = buffer.makeRenderCommandEncoder(descriptor: pass)
    else { return }
    encoder.setRenderPipelineState(pipeline)
    var u = uniforms
    encoder.setVertexBytes(&u.size, length: MemoryLayout<SIMD2<Float>>.size, index: 0)
    encoder.setFragmentBytes(&u.size, length: MemoryLayout<SIMD2<Float>>.size, index: 0)
    encoder.setFragmentBytes(&u.density, length: MemoryLayout<Float>.size, index: 1)
    encoder.setFragmentBytes(&u.shift, length: MemoryLayout<SIMD4<Float>>.size, index: 2)
    encoder.setFragmentBytes(&u.length, length: MemoryLayout<SIMD4<Float>>.size, index: 3)
    encoder.setFragmentBytes(&u.glow, length: MemoryLayout<Float>.size, index: 4)
    encoder.setFragmentBytes(&u.width, length: MemoryLayout<Float>.size, index: 5)
    encoder.setFragmentBytes(&u.boost, length: MemoryLayout<Float>.size, index: 6)
    encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 3)
    encoder.endEncoding()
    buffer.present(drawable)
    buffer.addCompletedHandler { buffer in gpuTime((buffer.gpuEndTime - buffer.gpuStartTime) * 1000) }
    buffer.commit()
  }
}

/// Frames per second, CPU and GPU time per frame, reported every 2 s.
private struct FrameStats {
  private var windowStart = CACurrentMediaTime()
  private var frames = 0
  private var cpuMillis = 0.0
  private var gpuFrames = 0
  private var gpuMillis = 0.0
  private var gpuMaxMillis = 0.0
  var ticks = 0  // animateOneFrame calls
  var missedDrawables = 0

  mutating func frame(cpuMillis: Double) {
    frames += 1
    self.cpuMillis += cpuMillis
  }

  mutating func gpuFrame(millis: Double) {
    gpuFrames += 1
    gpuMillis += millis
    gpuMaxMillis = max(gpuMaxMillis, millis)
  }

  mutating func report(now: CFTimeInterval) -> String? {
    let elapsed = now - windowStart
    guard elapsed >= 2 else { return nil }
    let text = String(
      format: "fps %.1f, ticks/s %.1f, cpu %.2f ms/frame, gpu %.2f ms avg %.2f max, missed drawables %d",
      Double(frames) / elapsed, Double(ticks) / elapsed, frames > 0 ? cpuMillis / Double(frames) : 0,
      gpuFrames > 0 ? gpuMillis / Double(gpuFrames) : 0, gpuMaxMillis, missedDrawables)
    self = FrameStats()
    return text
  }
}
